/**
 * The local browser's installer — ONE implementation used by `nexus-browser-doctor --install`, `cortex setup` (the install-time browser
 * option) and `cortex browser install`. Policy (operator 2026-11-03): choosing the local browser IS the approval, so everything it needs
 * is installed in that one step; nothing is ever installed at runtime without that choice, and a run with no person present never
 * prompts (it uses what it can do silently and reports the rest).
 *
 *   Chrome             found on the machine, else Chrome for Testing downloaded into the tools home (@puppeteer/browsers; no root)
 *   System tools       python3 (+venv), Xvfb (the sandbox's own display :99), xdotool, x11vnc — the first rung that works:
 *                      root → the package manager · passwordless sudo (`sudo -n`) · interactive only: `sudo` (may ask for the password)
 *                      · Nix (`nix-build`, GC-rooted under the tools home) · else the exact command to run, reported
 *   User space         a private Python venv with patchright / websockify / pymupdf / pdfplumber / beautifulsoup4; two extensions
 *
 * The result is written to <tools home>/install.json (chrome path, extra PATH for Nix tools, readiness). The library (local.ts, locate.ts)
 * and the harness read it, so a Nix-installed Xvfb or a downloaded Chrome needs no environment variable.
 */
import { execFileSync, spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { findChromium, resetChromiumCache } from './locate.js';

export const toolsHome = (): string => process.env.NEXUS_BROWSER_HOME ?? path.join(os.homedir(), '.nexus-cortex', 'browser');
const statePath = () => path.join(toolsHome(), 'install.json');

/** Optional parts beyond the core (Node + Chrome + extensions). 0.8.6: opt-in on macOS/Windows; Linux keeps both on by default (the hosted
 *  containers and bench boxes rely on the sandbox backend + PDF skills). The choice is remembered in install.json so `cortex update` keeps it. */
export interface InstallExtras { pdf?: boolean; sandbox?: boolean }
export const defaultExtras = (): Required<InstallExtras> => ({ pdf: process.platform === 'linux', sandbox: process.platform === 'linux' });
export interface InstallState { version: 1; at: string; chrome?: string; extraPath?: string; ready: { core: boolean; sandbox: boolean }; manual?: string[]; extras?: InstallExtras }

export function readInstallState(): InstallState | null {
  try { return JSON.parse(fs.readFileSync(statePath(), 'utf8')) as InstallState; } catch { return null; }
}
function writeInstallState(s: InstallState): void {
  fs.mkdirSync(toolsHome(), { recursive: true });
  fs.writeFileSync(statePath(), JSON.stringify(s, null, 2) + '\n');
}

/** Extra PATH entries: the environment's, then what the installer recorded (Nix tool dirs). */
export const extraPath = (): string => [process.env.NEXUS_BROWSER_EXTRA_PATH, readInstallState()?.extraPath].filter(Boolean).join(path.delimiter);

export function which(bin: string): string | null {
  for (const d of [extraPath(), process.env.PATH ?? ''].join(path.delimiter).split(path.delimiter)) {
    if (!d) continue;
    const p = path.join(d, bin);
    try { fs.accessSync(p, fs.constants.X_OK); if (fs.statSync(p).isFile()) return p; } catch { /* next */ }
  }
  return null;
}

const EXTENSIONS = [
  { name: 'ubol', label: 'uBlock Origin Lite', url: 'https://github.com/uBlockOrigin/uBOL-home/releases/download/2026.308.1810/uBOLite_2026.308.1810.chromium.zip' },
  { name: 'consent-o-matic', label: 'Consent-O-Matic', url: 'https://github.com/cavi-au/Consent-O-Matic/releases/download/v1.1.5/consent-o-matic-v1.1.5-unpacked-release-chromium.zip' },
];
const PIP_ALL = ['patchright', 'websockify', 'pymupdf', 'pdfplumber', 'beautifulsoup4'];
const SANDBOX_PIP = ['patchright', 'websockify'];
const PDF_PIP = ['pymupdf', 'pdfplumber', 'beautifulsoup4'];
// What pip is asked for. pymupdf < 2: 2.x pulls pymupdf_layout → onnxruntime + numpy (~200 MB of an AI layout model we never use).
const PIP_SPEC: Record<string, string> = { pymupdf: 'pymupdf<2' };
// 0.8.5 (operator's Mac, 11-13: "it wants to install another chrome instance in a venv"): patchright + websockify serve only the sandbox
// backend, which is Linux-only, so macOS / Windows get just the PDF libraries (~60 MB instead of ~255 MB).
const PIP = process.platform === 'linux' ? PIP_ALL : PIP_ALL.filter((p) => p !== 'patchright' && p !== 'websockify');
const PIP_IMPORT: Record<string, string> = { patchright: 'patchright', websockify: 'websockify', pymupdf: 'fitz', pdfplumber: 'pdfplumber', beautifulsoup4: 'bs4' };
const venvDir = () => path.join(toolsHome(), 'venv');
const venvPy = () => path.join(venvDir(), process.platform === 'win32' ? 'Scripts/python.exe' : 'bin/python');
const linux = process.platform === 'linux';
// The sandbox always runs its OWN Xvfb on :99 (the container contract) — the machine's DISPLAY is never used, so Xvfb is required on
// Linux whether or not a desktop is present (2026-11-03: Replit sets DISPLAY=:0 with no X server behind it).
const python3 = () => (fs.existsSync(venvPy()) ? venvPy() : which('python3'));
const pyHas = (mod: string) => { const py = python3(); return !!py && spawnSync(py, ['-c', `import ${mod}`], { stdio: 'ignore' }).status === 0; };

function resolveExtras(e?: InstallExtras): Required<InstallExtras> {
  const base = { ...defaultExtras(), ...(readInstallState()?.extras ?? {}) };
  const r = { pdf: e?.pdf ?? base.pdf, sandbox: e?.sandbox ?? base.sandbox };
  if (process.platform !== 'linux') r.sandbox = false;   // the sandbox backend is Linux-only
  return r;
}
const wantedPip = (x: Required<InstallExtras>) => [...(x.sandbox ? SANDBOX_PIP : []), ...(x.pdf ? PDF_PIP : [])];

export interface CheckRow { area: 'core' | 'sandbox' | 'live view' | 'pdf skills' | 'extensions'; item: string; ok: boolean; optional: boolean; fix?: string }

/** What is there and what is missing — the doctor's table; nothing is changed. */
export function checkAll(): CheckRow[] {
  const rows: CheckRow[] = [];
  const add = (area: CheckRow['area'], item: string, ok: boolean, fix?: string, optional = false) => rows.push({ area, item, ok, fix, optional });
  const nodeMajor = Number(process.versions.node.split('.')[0]);
  add('core', `Node ${process.versions.node}`, nodeMajor >= 20, 'install Node 20 or newer');
  const chrome = findChromium();
  add('core', `Chrome/Chromium${chrome ? ` (${chrome})` : ''}`, !!chrome, 'cortex browser install (downloads Chrome for Testing) or install Chrome / Chromium');
  add(process.platform === 'linux' ? 'sandbox' : 'pdf skills', 'python3', !!which('python3'), 'cortex browser install', process.platform !== 'linux');
  for (const p of PIP) add(p === 'patchright' || p === 'websockify' ? 'sandbox' : 'pdf skills', `python: ${p}`, pyHas(PIP_IMPORT[p]!), 'cortex browser install', p !== 'patchright' && p !== 'websockify');
  if (linux) {
    add('sandbox', 'Xvfb (virtual display on :99)', !!which('Xvfb'), 'cortex browser install');
    add('sandbox', 'xdotool (OS-level input)', !!which('xdotool'), 'cortex browser install');
    add('live view', 'x11vnc', !!which('x11vnc'), 'cortex browser install', true);
  } else {
    add('sandbox', `OS-level input on ${process.platform}`, false, 'the sandbox backend is Linux-only for now; the default backend works everywhere', true);
  }
  add('pdf skills', 'pdf2htmlEX', !!which('pdf2htmlEX'), 'optional — https://github.com/pdf2htmlEX/pdf2htmlEX/releases', true);
  for (const e of EXTENSIONS) add('extensions', e.label, fs.existsSync(path.join(toolsHome(), 'extensions', e.name, 'manifest.json')), 'cortex browser install', true);
  return rows;
}

export const readiness = (rows = checkAll()) => ({
  core: rows.filter((r) => r.area === 'core').every((r) => r.ok),
  sandbox: rows.filter((r) => r.area === 'sandbox' && !r.optional).every((r) => r.ok),
});

/** What an install would do (for the approval prompt). Sizes are approximate. */
export function installPlan(rows = checkAll(), extras?: InstallExtras): { steps: string[]; approxMB: number } {
  const steps: string[] = []; let mb = 0;
  const x = resolveExtras(extras);
  const missing = (item: RegExp) => rows.some((r) => !r.ok && item.test(r.item));
  if (missing(/^Chrome/)) { steps.push('Download Chrome for Testing into ' + path.join(toolsHome(), 'chrome')); mb += 350; }
  const sys = systemNeeds(x);
  if (sys.length) steps.push(`Install system tools: ${sys.join(', ')} (package manager with root / passwordless sudo / sudo at this terminal, else Nix)`);
  if (sys.length) mb += 60;
  const pyMissing = wantedPip(x).filter((p) => !pyHas(PIP_IMPORT[p]!));
  if (pyMissing.length) {
    steps.push(`Add Python packages ${pyMissing.join(', ')} in ${venvDir()} (it uses the packages your python3 already has; only what is missing is downloaded)`);
    mb += (pyMissing.includes('patchright') ? 190 : 0) + (pyMissing.some((p) => PDF_PIP.includes(p)) ? 60 : 0);
  }
  if (rows.some((r) => !r.ok && r.area === 'extensions')) { steps.push('Download the uBlock Origin Lite and Consent-O-Matic extensions'); mb += 5; }
  return { steps, approxMB: mb };
}

type Tool = 'python3' | 'Xvfb' | 'xdotool' | 'x11vnc';
function systemNeeds(x: Required<InstallExtras> = resolveExtras()): Tool[] {
  if (!linux) return [];
  const need: Tool[] = [];
  if (wantedPip(x).length && !which('python3')) need.push('python3');
  if (x.sandbox) {
    if (!which('Xvfb')) need.push('Xvfb');
    if (!which('xdotool')) need.push('xdotool');
    if (!which('x11vnc')) need.push('x11vnc');
  }
  return need;
}

const PM: Record<string, { probe: string; pkgs: Record<Tool, string[]>; cmd: (pkgs: string[]) => string[][] }> = {
  apt: { probe: 'apt-get', pkgs: { python3: ['python3', 'python3-venv'], Xvfb: ['xvfb'], xdotool: ['xdotool'], x11vnc: ['x11vnc'] },
    cmd: (p) => [['apt-get', 'update', '-qq'], ['apt-get', 'install', '-y', '-qq', '--no-install-recommends', ...p]] },
  apk: { probe: 'apk', pkgs: { python3: ['python3'], Xvfb: ['xvfb'], xdotool: ['xdotool'], x11vnc: ['x11vnc'] }, cmd: (p) => [['apk', 'add', '--no-cache', ...p]] },
  dnf: { probe: 'dnf', pkgs: { python3: ['python3'], Xvfb: ['xorg-x11-server-Xvfb'], xdotool: ['xdotool'], x11vnc: ['x11vnc'] }, cmd: (p) => [['dnf', 'install', '-y', '-q', ...p]] },
  pacman: { probe: 'pacman', pkgs: { python3: ['python'], Xvfb: ['xorg-server-xvfb'], xdotool: ['xdotool'], x11vnc: ['x11vnc'] }, cmd: (p) => [['pacman', '-S', '--noconfirm', '--needed', ...p]] },
};
const NIX_ATTR: Record<Tool, string> = { python3: 'python3', Xvfb: 'xorg.xvfb', xdotool: 'xdotool', x11vnc: 'x11vnc' };

export interface InstallOptions {
  /** A person is at this terminal (sudo may ask for a password). False = never prompt. */
  interactive: boolean;
  log?: (line: string) => void;
  /** Optional parts; omitted = what was chosen last time, else the platform default (defaultExtras). */
  extras?: InstallExtras;
}
export interface InstallResult { ready: { core: boolean; sandbox: boolean }; done: string[]; manual: string[]; state: InstallState }

/** Install everything the local browser needs. Call ONLY after the user chose the local browser (that choice is the approval). */
export async function installAll(opts: InstallOptions): Promise<InstallResult> {
  const log = opts.log ?? ((l: string) => process.stderr.write(l + '\n'));
  const done: string[] = []; const manual: string[] = [];
  const prev = readInstallState();
  const state: InstallState = { version: 1, at: new Date().toISOString(), ...(prev?.chrome ? { chrome: prev.chrome } : {}), ...(prev?.extraPath ? { extraPath: prev.extraPath } : {}), ready: { core: false, sandbox: false } };
  const x = resolveExtras(opts.extras);
  state.extras = x;
  fs.mkdirSync(toolsHome(), { recursive: true });

  // 1. Chrome.
  if (!findChromium() && !(state.chrome && fs.existsSync(state.chrome))) {
    log('Downloading Chrome for Testing (stable)…');
    try {
      const spec = '@puppeteer/browsers';   // shipped with puppeteer-core; a runtime import keeps it out of the bundle
      const b: any = await import(spec);
      const platform = b.detectBrowserPlatform();
      if (!platform) throw new Error(`no Chrome for Testing build for ${process.platform}/${process.arch}`);
      const buildId = await b.resolveBuildId(b.Browser.CHROME, platform, 'stable');
      const got = await b.install({ browser: b.Browser.CHROME, buildId, cacheDir: path.join(toolsHome(), 'chrome'), platform });
      state.chrome = got.executablePath; done.push(`Chrome for Testing ${buildId}`);
    } catch (e) { manual.push(`Chrome: ${String((e as Error).message).slice(0, 160)} — install Google Chrome or Chromium`); }
  }

  // 2. System tools (Linux).
  const need = systemNeeds(x);
  if (need.length) {
    const root = typeof process.getuid === 'function' && process.getuid() === 0;
    const hasSudo = !!which('sudo');
    const sudoN = hasSudo && spawnSync('sudo', ['-n', 'true'], { stdio: 'ignore' }).status === 0;
    const pm = Object.values(PM).find((m) => !!which(m.probe));
    const prefix = root ? [] : sudoN ? ['sudo', '-n'] : (opts.interactive && hasSudo) ? ['sudo'] : null;
    let installed = false;
    if (pm && prefix) {
      log(`Installing ${need.join(', ')} with ${pm.probe}${prefix.length ? ` (${prefix.join(' ')})` : ''}…`);
      const pkgs = need.flatMap((t) => pm.pkgs[t]);
      installed = pm.cmd(pkgs).every(([bin, ...args]) => spawnSync(prefix[0] ?? bin!, prefix.length ? [...prefix.slice(1), bin!, ...args] : args,
        { stdio: opts.interactive ? 'inherit' : ['ignore', 'ignore', 'pipe'], env: { ...process.env, DEBIAN_FRONTEND: 'noninteractive' } }).status === 0);
      if (installed) done.push(`${need.join(', ')} via ${pm.probe}`);
    }
    if (!installed && which('nix-build')) {
      log(`Installing ${need.join(', ')} from Nix…`);
      const dirs: string[] = [];
      for (const t of need) {
        const link = path.join(toolsHome(), 'nix', t);   // an out-link is a GC root: the tool survives nix-collect-garbage
        fs.mkdirSync(path.dirname(link), { recursive: true });
        const r = spawnSync('nix-build', ['<nixpkgs>', '-A', NIX_ATTR[t], '--out-link', link], { stdio: ['ignore', 'pipe', 'pipe'], encoding: 'utf8' });
        if (r.status === 0 && fs.existsSync(path.join(link, 'bin'))) dirs.push(path.join(link, 'bin'));
        else manual.push(`${t}: nix-build ${NIX_ATTR[t]} failed`);
      }
      if (dirs.length) {
        state.extraPath = [...new Set([...(state.extraPath ? state.extraPath.split(path.delimiter) : []), ...dirs])].join(path.delimiter);
        writeInstallState(state);   // which() reads it from here on
        done.push(`${need.filter((t) => dirs.some((d) => d.includes(`${path.sep}nix${path.sep}${t}${path.sep}`))).join(', ')} via Nix`);
      }
      installed = dirs.length === need.length;
    }
    if (!installed) {
      const still = systemNeeds(x);
      if (still.length) {
        const cmd = pm ? `sudo ${pm.cmd(still.flatMap((t) => pm.pkgs[t])).map((c) => c.join(' ')).join(' && sudo ')}` : `install ${still.join(', ')} with your package manager`;
        manual.push(`system tools ${still.join(', ')}: ${cmd}`);
      }
    }
  }

  // 3. Python packages, only for the extras chosen. Reuse first (0.8.6, operator: "install once and reuse — don't re-download what already
  // exists"): anything the system python3 can already import is used as is; a venv is made only for what is missing, with
  // --system-site-packages, and pip installs into it — pip counts the system's packages as satisfying dependencies (uv re-resolves and
  // re-downloads them: measured 11-13, 113 MB vs 102 MB with pillow/cryptography/pdfminer duplicated), so only what is missing is fetched.
  const py = which('python3');
  const want = wantedPip(x);
  if (py && want.length && want.some((p) => !pyHas(PIP_IMPORT[p]!))) {
    if (!fs.existsSync(venvPy())) {
      log(`Creating the Python environment ${venvDir()} (it also sees your python3's packages)…`);
      const ok = spawnSync(py, ['-m', 'venv', '--system-site-packages', venvDir()], { stdio: opts.interactive ? 'inherit' : 'ignore' }).status === 0;
      if (!ok) manual.push('python venv: install python3-venv (Debian/Ubuntu) and re-run');
    }
    const missing = want.filter((p) => !pyHas(PIP_IMPORT[p]!));
    if (missing.length && fs.existsSync(venvPy())) {
      log(`Installing Python packages: ${missing.join(' ')}…`);
      // A global pip.conf (user = true) would break a venv install.
      const env = { ...process.env, PIP_CONFIG_FILE: os.devnull, PIP_USER: '0' };
      const r = spawnSync(venvPy(), ['-m', 'pip', 'install', '-q', ...missing.map((p) => PIP_SPEC[p] ?? p)], { stdio: opts.interactive ? 'inherit' : ['ignore', 'ignore', 'pipe'], env });
      if (r.status === 0) done.push(`python: ${missing.join(', ')}`); else manual.push(`python packages ${missing.join(', ')}: install failed`);
    }
  }

  // 4. Extensions.
  const extDir = path.join(toolsHome(), 'extensions');
  fs.mkdirSync(extDir, { recursive: true });
  for (const e of EXTENSIONS) {
    if (fs.existsSync(path.join(extDir, e.name, 'manifest.json'))) continue;
    const zip = path.join(os.tmpdir(), `nexus-browser-${e.name}-${process.pid}.zip`);
    try {
      execFileSync('curl', ['-fsSL', '-o', zip, e.url], { stdio: 'ignore' });
      // unzip first (built into macOS and most Linux): on a fresh Mac `python3` is only a stub that pops up the developer-tools installer.
      const unzip = which('unzip');
      if (unzip) execFileSync(unzip, ['-q', '-o', zip, '-d', path.join(extDir, e.name)], { stdio: 'ignore' });
      else {
        const pyx = python3();
        if (!pyx) throw new Error('unzip or python3 is needed to unpack it');
        execFileSync(pyx, ['-c', `import zipfile; zipfile.ZipFile(${JSON.stringify(zip)}).extractall(${JSON.stringify(path.join(extDir, e.name))})`]);
      }
      done.push(e.label);
    } catch (err) { manual.push(`${e.label}: ${String((err as Error).message).slice(0, 120)}`); }
    fs.rmSync(zip, { force: true });
  }

  // 2026-11-06 (om2w Vast box): findChromium() reads the downloaded Chrome's path from install.json, which used to be written only AFTER this
  // check — on a fresh machine with no system Chrome the install downloaded Chrome and still recorded core NOT ready. Persist first, then check.
  writeInstallState(state);
  resetChromiumCache();   // the Chrome step above looked BEFORE the download and memoized "none"
  const rows = checkAll();
  state.ready = readiness(rows);
  state.manual = manual;
  state.at = new Date().toISOString();
  writeInstallState(state);
  return { ready: state.ready, done, manual, state };
}
