/**
 * Find a Chromium/Chrome binary to drive. Order: NEXUS_BROWSER_CHROMIUM / PUPPETEER_EXECUTABLE_PATH /
 * PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH, known install paths, then PATH. Returns null when none is found — callers report
 * "browser unavailable" instead of crashing (the module is optional).
 */
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';

const ENV_KEYS = ['NEXUS_BROWSER_CHROMIUM', 'PUPPETEER_EXECUTABLE_PATH', 'PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH'];
const KNOWN = [
  '/repl/tools/bin/chromium',                                   // Replit
  '/usr/bin/chromium', '/usr/bin/chromium-browser', '/usr/bin/google-chrome-stable', '/usr/bin/google-chrome',
  '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  '/Applications/Chromium.app/Contents/MacOS/Chromium',
  'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
  'C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe',
];
const ON_PATH = ['chromium', 'chromium-browser', 'google-chrome-stable', 'google-chrome', 'chrome'];

function executable(p: string): boolean {
  try { fs.accessSync(p, fs.constants.X_OK); return fs.statSync(p).isFile(); } catch { return false; }
}

/** Playwright's own browser cache (a harness that already ran `playwright install chromium`). */
function playwrightCache(): string[] {
  const root = process.env.PLAYWRIGHT_BROWSERS_PATH || path.join(os.homedir(), '.cache', 'ms-playwright');
  try {
    return fs.readdirSync(root).filter((d) => /^chromium-\d+$/.test(d)).sort().reverse()
      .flatMap((d) => [path.join(root, d, 'chrome-linux', 'chrome'), path.join(root, d, 'chrome-linux64', 'chrome')]);
  } catch { return []; }
}

let cached: string | null | undefined;
/** Forget the memoized lookup — the installer calls this after it downloads Chrome (2026-11-06: the pre-download null was cached, so a fresh
 *  install recorded core NOT ready). */
export function resetChromiumCache(): void { cached = undefined; }
export function findChromium(): string | null {
  if (cached !== undefined) return cached;
  for (const k of ENV_KEYS) { const v = process.env[k]; if (v && executable(v)) return (cached = v); }
  const installed = installedChrome(); if (installed && executable(installed)) return (cached = installed);   // `cortex browser install` download
  for (const p of [...KNOWN, ...playwrightCache()]) if (executable(p)) return (cached = p);
  for (const dir of (process.env.PATH || '').split(path.delimiter)) {
    for (const n of ON_PATH) { const p = path.join(dir, n); if (executable(p)) return (cached = p); }
  }
  return (cached = null);
}

/** The Chrome the installer downloaded (<tools home>/install.json; read directly — install.ts imports this module). */
function installedChrome(): string | undefined {
  const home = process.env.NEXUS_BROWSER_HOME ?? path.join(os.homedir(), '.nexus-cortex', 'browser');
  try { return (JSON.parse(fs.readFileSync(path.join(home, 'install.json'), 'utf8')) as { chrome?: string }).chrome; } catch { return undefined; }
}
